package renderers

import (
	"bytes"
	"encoding/json"
	"flag"
	"os"
	"path/filepath"
	"reflect"
	"testing"
)

// The golden files were generated by running the TypeScript renderers on the
// same *.input.json fixtures, so they pin byte-for-byte parity. Regenerating
// them from Go with -update is only valid after a deliberate output change.
var update = flag.Bool("update", false, "rewrite golden files from the current Go output")

func loadFixture(t *testing.T, name string, target any) {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join("testdata", name+".input.json"))
	if err != nil {
		t.Fatalf("read fixture %s: %v", name, err)
	}
	if err := json.Unmarshal(raw, target); err != nil {
		t.Fatalf("decode fixture %s: %v", name, err)
	}
}

// assertGolden compares a rendered candidate with testdata/<name>.golden.json.
func assertGolden[T any](t *testing.T, name string, got T) {
	t.Helper()
	path := filepath.Join("testdata", name+".golden.json")
	if *update {
		var buffer bytes.Buffer
		encoder := json.NewEncoder(&buffer)
		encoder.SetEscapeHTML(false)
		encoder.SetIndent("", "  ")
		if err := encoder.Encode(got); err != nil {
			t.Fatalf("encode golden: %v", err)
		}
		if err := os.WriteFile(path, buffer.Bytes(), 0o644); err != nil {
			t.Fatalf("write golden: %v", err)
		}
		return
	}
	raw, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("read golden %s: %v", name, err)
	}
	var want T
	if err := json.Unmarshal(raw, &want); err != nil {
		t.Fatalf("decode golden %s: %v", name, err)
	}
	if !reflect.DeepEqual(got, want) {
		gotJSON, _ := json.MarshalIndent(got, "", "  ")
		wantJSON, _ := json.MarshalIndent(want, "", "  ")
		t.Fatalf("output differs from golden %s\n--- want ---\n%s\n--- got ---\n%s", name, wantJSON, gotJSON)
	}
}
